SEC = [
 (86, 'విద్యుత్ ఉపయోగాలు, కృత్యం 3.1', [
  'వంట: ఇండక్షన్ స్టవ్, రైస్ కుక్కర్. వెలుతురు: పాఠశాలలు, ఆసుపత్రులు. రవాణా: మెట్రో రైలు, ఇ-రిక్షా. వేడి–చల్లదనం: కూలర్, ఇస్త్రీ పెట్టె. వినోదం: కంప్యూటర్ ఆటలు, సినిమా హాలు, స్పీకర్లు. సమాచారం: టెలిఫోన్, కంప్యూటర్. ఇతరాలు: వాషింగ్ మెషిన్, కుట్టు మిషన్, వైద్య పరికరాలు.',
  'ఇతర వర్గీకరణలు: ఇంట్లో/పాఠశాలలో/పొలంలో/పరిశ్రమలో వాడేవి; బ్యాటరీతో పనిచేసేవి/సాకెట్‌తో పనిచేసేవి.',
  '3.1) టార్చిలో బల్బు, స్విచ్ ఉంటాయి. స్విచ్ ఒక స్థానంలో బల్బు వెలుగుతుంది, మరో స్థానంలో వెలగదు. లోపల రెండు లేదా ఎక్కువ ఘటాలు ఉంటాయి.']),
 (88, 'కృత్యం 3.2, 3.3 – ఘటం, బ్యాటరీ', [
  '3.2) ఘటంపై + , – గుర్తులు ఉంటాయి. ఉబ్బెత్తు లోహపు మూత = ధన ధ్రువం; చదునైన లోహపు బిళ్ళ = రుణ ధ్రువం.',
  '3.3) ఒక ఘటం ధన ధ్రువం తర్వాతి ఘటం రుణ ధ్రువాన్ని తాకేలా పెట్టినప్పుడే బల్బు వెలుగుతుంది. ఒక ఘటాన్ని తిప్పి పెడితే వెలగదు.']),
 (90, 'కృత్యం 3.4 – ఫిలమెంట్ బల్బు', [
  '1. గాజు బుడ్డి మధ్యలో సన్నని తీగ ఉంటుంది. 2. టార్చి ఆన్ చేస్తే ఆ సన్నని తీగ (ఫిలమెంట్) వెలుగుతుంది. 3. ఫిలమెంట్ రెండు మందపు తీగలకు అతికి ఉంటుంది – ఒకటి ఆధారం లోహపు తొడుగుకు, మరొకటి మధ్య లోహపు మొనకు; ఇవే బల్బు రెండు ధ్రువాలు.']),
 (92, 'కృత్యం 3.5 – LED', [
  '1. LED లో ఫిలమెంట్ ఉండదు. 2. రెండు తీగల్లో ఒకటి పొడవు (ధన), మరొకటి పొట్టి (రుణ).']),
 (96, 'కృత్యం 3.6 – పట్టిక 3.1 (బల్బు వెలిగించడం)', [
  'పుస్తకం ప్రకారం: క్రమ సంఖ్య 1, 6 అమరికల్లో బల్బు వెలుగుతుంది; 2, 3, 4, 5 అమరికల్లో వెలగదు.',
  'కారణం: బల్బు ఒక ధ్రువం ఘటం ఒక ధ్రువానికి, బల్బు రెండో ధ్రువం ఘటం రెండో ధ్రువానికి కలిసినప్పుడే వలయం పూర్తవుతుంది. రెండు తీగలూ ఒకే ధ్రువానికి కలిసినా, ఒక తీగ విడిగా ఉన్నా వలయం పూర్తికాదు.']),
 (100, 'కృత్యం 3.7 – LED వెలిగించడం', [
  '1. బ్యాటరీ ధన ధ్రువం: ఒక ఘటం ధన ధ్రువానికి కలిసిన హోల్డర్ చివర. 2. LED పొడవు తీగను బ్యాటరీ ధన ధ్రువానికి, పొట్టి తీగను రుణ ధ్రువానికి కలిపితే వెలుగుతుంది. 3. తీగలు మార్చి కలిపితే వెలగదు – LED లో ప్రవాహం ఒకే దిశలో వెళుతుంది.',
  'పక్కపక్కన ఘటాలు: లోపల మందపు తీగ/లోహపు పట్టీ ఒక ఘటం ధన ధ్రువాన్ని పక్క ఘటం రుణ ధ్రువానికి కలుపుతుంది.']),
 (102, 'కృత్యం 3.8, 3.9 – స్విచ్', [
  '1. పిన్నీసు రెండో డ్రాయింగ్ పిన్‌ను తాకనప్పుడు (OFF) బల్బు వెలగదు – వలయంలో ఖాళీ ఉంది (తెరిచిన వలయం). 2. తాకినప్పుడు (ON) ఖాళీ మూసుకొని వలయం పూర్తవుతుంది – బల్బు వెలుగుతుంది (మూసిన వలయం).']),
 (106, 'కృత్యం 3.10 – వలయ పటాలు', [
  'పటం 3.12a: ఒక ఘటం గుర్తు, బల్బు గుర్తు, OFF స్థితిలో స్విచ్ గుర్తు – తీగలతో ఒకే వలయంగా (పటం 3.14a లాగా).',
  'పటం 3.10c: రెండు ఘటాల బ్యాటరీ గుర్తు, LED గుర్తు – LED త్రిభుజం వైపు (ధన) బ్యాటరీ పొడవు గీత (ధన) వైపు కలిసేలా (పటం 3.14b లాగా).']),
 (108, 'కృత్యం 3.11 – శ్రేణి సంధానం', [
  '1. స్విచ్ ON చేస్తే మూడు బల్బులూ వెలుగుతాయి – ప్రవాహం అన్నింటి గుండా ఒకే మార్గంలో వెళుతుంది. 2. ఒక బల్బు తీసి ON చేస్తే మిగిలిన బల్బులు వెలగవు – వలయంలో ఖాళీ ఏర్పడి తెరిచిన వలయం అవుతుంది.']),
 (110, 'కృత్యం 3.12 – సమాంతర సంధానం', [
  '1. స్విచ్ ON చేస్తే అన్ని బల్బులూ వెలుగుతాయి. 2. ఒక బల్బు తీసినా మిగిలిన రెండూ వెలుగుతూనే ఉంటాయి – ప్రతి బల్బుకు బ్యాటరీతో వేరు మార్గం ఉంది.']),
 (114, 'కృత్యం 3.13 – పట్టిక 3.3 (వాహకాలు, బంధకాలు)', [
  'వస్తువు | పదార్థం | బల్బు వెలుగుతుందా | ముగింపు | పుల్ల | చెక్క | లేదు | బంధకం | స్కేలు | ప్లాస్టిక్ | లేదు | బంధకం | గాజు | గాజు | లేదు | బంధకం | కాగితపు ముక్క | కాగితం | లేదు | బంధకం | కొవ్వొత్తి | మైనం | లేదు | బంధకం | తాళం చెవి | లోహం | అవును | వాహకం | రబ్బరు | రబ్బరు | లేదు | బంధకం | నాణెం/చెంచా/సూది | లోహం | అవును | వాహకం | అల్యూమినియం రేకు | అల్యూమినియం | అవును | వాహకం | పెన్సిల్ ముల్లు | గ్రాఫైట్ | అవును | వాహకం',
  'ముగింపు: లోహాలు వాహకాలు – అందుకే తీగలు లోహంతో చేస్తారు. ప్లాస్టిక్, రబ్బరు బంధకాలు – అందుకే తీగలపై వాటి పొర వేస్తారు.']),
 (118, 'మన అభ్యసనాన్ని మెరుగుపరచుకుందాం – ప్ర.1', [
  '1) D : S. (S లో పొడవు–పొట్టి గీతల జతలు రెండు ఉన్నాయి = బ్యాటరీ. P = ఒక ఘటం, Q = బల్బు, R = స్విచ్.)']),
 (120, 'ప్ర.2–8', [
  '2) C – స్విచ్ తెరిచి ఉంది కాబట్టి వలయం అసంపూర్ణం; బల్బు వెలగదు.',
  '3) (i) తప్పు. స్విచ్ విద్యుత్ వనరు కాదు; వనరు ఘటం/బ్యాటరీ. స్విచ్ వలయాన్ని కలుపుతుంది లేదా తెంచుతుంది.',
  '4) B – తాళం చెవి బంధకం, ఇనుప మేకు వాహకం.',
  '5) a) వాహకాలు: విద్యుత్ ప్రవాహాన్ని సులభంగా పోనిచ్చే పదార్థాలు (రాగి, ఇనుము). b) బంధకాలు: ప్రవాహాన్ని పోనివ్వని పదార్థాలు (రబ్బరు, ప్లాస్టిక్). c) విద్యుత్ ఘటం: ధన, రుణ ధ్రువాలున్న, తీసుకెళ్లగల విద్యుత్ శక్తి వనరు. d) స్విచ్: వలయాన్ని పూర్తి చేసే లేదా తెంచే సాధనం. e) వలయ పటం: గుర్తులతో వలయాన్ని చూపే చిత్రం.',
  '6) ఏదైనా బంధకం – రబ్బరు, ప్లాస్టిక్, చెక్క, గాజు, కాగితం – A, B మధ్య కలిపితే బల్బు వెలగదు.',
  '7) 1. బ్యాటరీకి రెండు తీగలు కట్టి LED కి కలపాలి. 2. LED వెలిగితే LED పొడవు తీగకు కలిసిన బ్యాటరీ చివర ధన ధ్రువం, పొట్టి తీగకు కలిసినది రుణ ధ్రువం. 3. వెలగకపోతే తీగలు మార్చి చూడాలి. (ఆకారం బట్టి కూడా: లోహపు మూత వైపు ధన, చదును వైపు రుణ.)',
  '8) వెలగదు. తీగ పైపొర బంధకం; లోహ భాగాలు ఒకదానినొకటి తాకకపోతే వలయం పూర్తికాదు, ప్రవాహం ఉండదు.']),
 (122, 'ప్ర.9–12', [
  '9) L1, S2, L2, బ్యాటరీ, S1 అన్నీ ఒకే మార్గంలో (శ్రేణిలో) ఉన్నాయి. కాబట్టి: (i) ఏ బల్బూ వెలగదు (ii) ఏ బల్బూ వెలగదు (iii) L1, L2 రెండూ వెలుగుతాయి (iv) ఏ బల్బూ వెలగదు.',
  '10) కారణాలు: 1. బల్బు ఫ్యూజ్ అయి ఉండవచ్చు. 2. ఘటం అయిపోయి ఉండవచ్చు. 3. తీగల కనెక్షన్లు వదులుగా ఉండవచ్చు. 4. తీగ చివర్ల ప్లాస్టిక్ పొర తీయకపోవచ్చు. 5. తీగ లోపల తెగి ఉండవచ్చు. 6. బల్బు హోల్డర్‌లో సరిగ్గా బిగించకపోవచ్చు. | కనుక్కోవడం: ఒక్కో భాగాన్ని మార్చి చూడాలి – కొత్త ఘటం, పనిచేసే బల్బు, వేరే తీగలు పెట్టి, కనెక్షన్లు బిగించి పరీక్షించాలి.',
  '11) (a), (b): ఫిలమెంట్ బల్బులు – ఘటం ఏ దిశలో ఉన్నా స్విచ్ మూస్తే వెలుగుతాయి. (c), (d): LED – త్రిభుజం మొన చూపే దిశలోనే ప్రవాహం వెళ్లాలి. ప్రవాహం బ్యాటరీ పొడవు గీత (ధన) నుండి బయలుదేరుతుంది. పటం ప్రకారం (c) లో ధన ధ్రువం LED త్రిభుజం మొన వైపు కలిసింది (ప్రవాహం వ్యతిరేక దిశ) → (c) లో LED వెలగదు; (d) లో వెలుగుతుంది. (మీ పుస్తకం పటంలో పొడవు గీత ఏ వైపు ఉందో చూసి సరిచూసుకోండి.)',
  '12) వెలగదు. పటంలో రెండు ఘటాల రుణ ధ్రువాలను (–, –) నల్ల తీగతో కలిపారు; రెండు ధన ధ్రువాలు LED కి వెళ్ళాయి – ఇది సరైన శ్రేణి కాదు, ప్రవాహం ఉండదు. | సరైన పద్ధతి: 1. ఒక ఘటం ధన ధ్రువాన్ని మరో ఘటం రుణ ధ్రువానికి కలపాలి. 2. మిగిలిన ధన ధ్రువాన్ని LED పొడవు తీగకు కలపాలి. 3. మిగిలిన రుణ ధ్రువాన్ని LED పొట్టి తీగకు కలపాలి.']),
 (124, 'ప్ర.13–16, ప్రాజెక్టులు', [
  '13) వెలగదు. రెండు బల్బులూ శ్రేణిలో ఉన్నాయి – ఒకే మార్గం. ఒక ఫిలమెంట్ తెగితే వలయం తెరుచుకొని ప్రవాహం ఆగిపోతుంది.',
  '14) టార్చి వలయ పటం: రెండు ఘటాల బ్యాటరీ గుర్తు → స్విచ్ గుర్తు → బల్బు గుర్తు → తిరిగి బ్యాటరీకి, అన్నీ ఒకే వలయంలో తీగలతో కలిపి గీయాలి.',
  '15) (i) కావలసినవి: టార్చి బల్బు (హోల్డర్‌తో), ఘటం హోల్డర్, తీగలు, ఆరు ఘటాలు. (ii) పద్ధతి: బల్బు, హోల్డర్‌తో వలయం కట్టాలి. ముందు పనిచేస్తుందని తెలిసిన ఘటంతో బల్బు సరిగా ఉందో చూడాలి. తర్వాత A నుండి F వరకు ఒక్కో ఘటాన్ని పెట్టి చూడాలి. (iii) బల్బు వెలిగితే ఆ ఘటం పనిచేస్తోంది; వెలగకపోతే పనిచేయడం లేదు. పట్టికలో రాయాలి.',
  '16) శ్రేణి: బ్యాటరీ → స్విచ్ → బల్బు → LED → మోటార్ → బ్యాటరీ (ఒకే వలయం; LED ధన చివర బ్యాటరీ ధన వైపు). సమాంతర: బ్యాటరీ, స్విచ్ తర్వాత తీగ మూడు శాఖలుగా – ఒక శాఖలో బల్బు, రెండో శాఖలో LED, మూడో శాఖలో మోటార్ – మళ్ళీ కలిసి బ్యాటరీకి.',
  'ప్రాజెక్టు – రెండు రోజులు కరెంటు లేకపోతే చేయలేనివి: ఫ్యాన్/లైట్, మొబైల్ ఛార్జింగ్, నీటి మోటార్, ఫ్రిజ్, టీవీ, మిక్సీ, ఆన్‌లైన్ తరగతులు.',
  'ఇంటి వస్తువులు – (i) బంధకాలు మాత్రమే: ప్లాస్టిక్ బకెట్, చెక్క కుర్చీ. (ii) వాహకాలు మాత్రమే: స్టీలు గిన్నె, తాళం చెవి. (iii) రెండూ: స్క్రూడ్రైవర్, ప్లగ్, విద్యుత్ తీగ, స్విచ్.']),
]
